def transform(grid):
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    for r, row in enumerate(grid):
        marks = [c for c, v in enumerate(row) if v != bg]
        for a, b in zip(marks, marks[1:]):
            if row[a] == row[b]:
                for c in range(a + 1, b):
                    if row[c] == bg:
                        out[r][c] = 2
    return out
